package pager

import (
	"reflect"
	"testing"
)

func TestPage(t *testing.T) {
	items := []string{"a", "b", "c", "d", "e"}
	cases := []struct {
		page, size int
		want       []string
	}{
		{1, 2, []string{"a", "b"}},
		{2, 2, []string{"c", "d"}},
		{3, 2, []string{"e"}},
		{4, 2, nil},
		{1, 5, items},
		{1, 10, items},
		{0, 2, nil},
		{1, 0, nil},
		{-1, 2, nil},
	}
	for _, c := range cases {
		got := Page(items, c.page, c.size)
		if len(got) == 0 && len(c.want) == 0 {
			continue
		}
		if !reflect.DeepEqual(got, c.want) {
			t.Errorf("Page(%d, %d) = %v, want %v", c.page, c.size, got, c.want)
		}
	}
	if got := Page(nil, 1, 3); len(got) != 0 {
		t.Errorf("Page(nil) = %v", got)
	}
}

func TestPageCount(t *testing.T) {
	for _, c := range []struct{ n, size, want int }{{0, 2, 0}, {1, 2, 1}, {2, 2, 1}, {3, 2, 2}, {5, 2, 3}, {5, 5, 1}, {5, 0, 0}, {5, -1, 0}} {
		if got := PageCount(c.n, c.size); got != c.want {
			t.Errorf("PageCount(%d, %d) = %d, want %d", c.n, c.size, got, c.want)
		}
	}
}

func TestPageDoesNotAliasWhenTrimmed(t *testing.T) {
	items := []string{"a", "b", "c"}
	got := Page(items, 2, 2)
	if len(got) != 1 || got[0] != "c" {
		t.Fatalf("got %v", got)
	}
	got = append(got, "z")
	if len(items) != 3 {
		t.Fatal("appending to a page must not touch the source slice")
	}
}

